  function cloneData(value) {
    if (typeof structuredClone === "function") return structuredClone(value);
    return JSON.parse(JSON.stringify(value));
  }

  function getNested(obj, path) {
    return path.split(".").reduce((acc, key) => acc?.[key], obj);
  }

  /** ko.json을 베이스로, 대상 locale에 있는 값만 덮어씀 (누락 키는 한국어 fallback) */
  function deepMergeFallback(base, override) {
    if (!override || typeof override !== "object" || Array.isArray(override)) {
      return override !== undefined && override !== null && override !== ""
        ? override
        : base;
    }
    if (!base || typeof base !== "object" || Array.isArray(base)) {
      return JSON.parse(JSON.stringify(override));
    }

    const result = cloneData(base);
    for (const key of Object.keys(override)) {
      const baseVal = base[key];
      const overrideVal = override[key];
      if (
        overrideVal &&
        typeof overrideVal === "object" &&
        !Array.isArray(overrideVal)
      ) {
        result[key] = deepMergeFallback(baseVal || {}, overrideVal);
      } else if (
        overrideVal !== undefined &&
        overrideVal !== null &&
        overrideVal !== ""
      ) {
        result[key] = overrideVal;
      }
    }
    return result;
  }

  function t(key, vars = {}) {
    let value = getNested(dict, key);
    if (value == null) return key;
    if (typeof value !== "string") return String(value);
    return Object.entries(vars).reduce(
      (str, [k, v]) => str.replace(new RegExp(`\\{${k}\\}`, "g"), v),
      value
    );
  }

