  function memberBioHtml(page) {
    if (Array.isArray(page.bio) && page.bio.length) {
      return `<ul class="member-bio">${page.bio
        .map((line) => `<li>${line}</li>`)
        .join("")}</ul>`;
    }

    if (!page.desc) return "";
    return `<p class="overlay-desc">${page.desc}</p>`;
  }

  function memberPageHtml(pageKey) {
    const page = getNested(dict, `pages.${pageKey}`);
    const instagramLink = page.instagram
      ? `<a href="${page.instagram}" class="member-profile__instagram" target="_blank" rel="noopener noreferrer" aria-label="${t(
          "overlay.instagram"
        )}">
          <span class="member-profile__instagram-icon">${memberInstagramIcon()}</span>
        </a>`
      : "";

    return `
        <div class="member-profile">
          <span class="member-profile__name">${page.name}</span>
          ${instagramLink}
        </div>
        ${memberBioHtml(page)}`;
  }

